// ❌ MAL: GetComponent y Find en Update — muy costoso
void Update()
{
    GetComponent<Rigidbody>().AddForce(Vector3.up); // GetComponent 60x/seg
    GameObject.Find("HUD").SetActive(true);         // Find busca TODA la escena
    Camera.main.transform.position = ...;           // FindObjectOfType 60x/seg
}

// ✅ BIEN: cachear en Awake/Start
private Rigidbody _rb;
private GameObject _hud;
private Camera _mainCam;

void Awake()
{
    _rb = GetComponent<Rigidbody>();
    _hud = GameObject.Find("HUD"); // una sola vez está bien
    _mainCam = Camera.main;
}

void Update()
{
    _rb.AddForce(Vector3.up);          // ✅ O(1)
    _hud.SetActive(true);              // ✅ O(1)
    _mainCam.transform.position = ...; // ✅ O(1)
}

// ❌ MAL: concatenación de strings en bucle genera basura para el GC
void BuildHUD(List<Enemy> enemies)
{
    string result = "";
    foreach (Enemy e in enemies)
    {
        result += e.name + ": " + e.health + "\n"; // crea nuevo string CADA iteración
    }
    hudText.text = result;
}
// Con 50 enemigos: 50 strings temporales creados y descartados → presión en el GC

// ✅ BIEN: StringBuilder reutiliza el buffer interno
void BuildHUD(List<Enemy> enemies)
{
    System.Text.StringBuilder sb = new System.Text.StringBuilder();
    foreach (Enemy e in enemies)
    {
        sb.Append(e.name).Append(": ").Append(e.health).AppendLine();
    }
    hudText.text = sb.ToString(); // una sola conversión a string al final
}

